const orderNumber = $('Find the order number').item.json.orderNumber;
const sender = String($('Find the order number').item.json.customerPhone);
const order = $json.data?.orders?.nodes?.[0];

// Compare the last 9 digits so +44 7700 900123 and 07700 900123 match.
const last9 = (p) => String(p ?? '').replace(/\D/g, '').slice(-9);
const phones = [order?.phone, order?.customer?.phone, order?.shippingAddress?.phone].map(last9).filter(Boolean);

let reply;
if ($json.errors?.length) {
  // Usually a missing scope or protected customer data access. Details are in this execution's log.
  reply = "Sorry, I can't check orders right now. A member of the team will reply here soon.";
} else if (!order) {
  reply = `I couldn't find order #${orderNumber}. Please check the number in your confirmation email and send it again.`;
} else if (!phones.includes(last9(sender))) {
  reply = `I found order ${order.name}, but this WhatsApp number isn't the one on the order, so I can't share its details here. Please message us from the number you used at checkout, or reply "human" and the team will help.`;
} else if (order.cancelledAt) {
  reply = `Order ${order.name} was cancelled. If that's unexpected, reply here and the team will look into it.`;
} else {
  const status = {
    UNFULFILLED: 'is being prepared',
    OPEN: 'is being prepared',
    PENDING_FULFILLMENT: 'is being prepared',
    IN_PROGRESS: 'is being prepared',
    ON_HOLD: 'is on hold',
    SCHEDULED: 'is scheduled to ship',
    PARTIALLY_FULFILLED: 'has partly shipped',
    FULFILLED: 'has shipped',
    RESTOCKED: 'was returned to stock',
  }[order.displayFulfillmentStatus] ?? `status: ${String(order.displayFulfillmentStatus).toLowerCase()}`;

  const tracking = (order.fulfillments ?? [])
    .flatMap((f) => f.trackingInfo ?? [])
    .filter((t) => t.url || t.number)
    .map((t) => `${t.company ?? 'Tracking'}: ${t.url ?? t.number}`);

  reply = `Order ${order.name} ${status}.`;
  if (order.displayFinancialStatus === 'PENDING') reply += ' Payment is still pending.';
  if (tracking.length) reply += `\n${tracking.join('\n')}`;
}

return { json: { reply } };
